package com.bank.vcs;

import java.util.ArrayList;
import java.util.List;

// A branch is an ordered, mutable line of commits with a HEAD you can commit onto.
public class Branch {
    private final String name;
    private final List<Commit> commits = new ArrayList<>();

    public Branch(String name) { this.name = name; }

    public String getName() { return name; }
    public void add(Commit c) { commits.add(c); }
    public List<Commit> getCommits() { return commits; }
    public Commit head() { return commits.isEmpty() ? null : commits.get(commits.size() - 1); }
    public boolean contains(String commitId) {
        return commits.stream().anyMatch(c -> c.getId().equals(commitId));
    }
}
