package com.bank.vcs;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// A tiny repo supporting the production/development two-branch model.
public class Repo {
    private static final Logger log = Logger.getLogger(Repo.class.getName());
    private final Map<String, Branch> branches = new HashMap<>();
    private int seq = 0;

    public Branch createBranch(String name, Branch from) {
        Branch b = new Branch(name);
        if (from != null) b.getCommits().addAll(from.getCommits());  // branch off = copy history
        branches.put(name, b);
        log.info(() -> "branch '" + name + "' created" + (from != null ? " from '" + from.getName() + "'" : ""));
        return b;
    }

    public Commit commit(Branch b, String message) {
        Commit c = new Commit("c" + (++seq), message);
        b.add(c);
        log.info(() -> "commit on '" + b.getName() + "': " + c);
        return c;
    }

    // Merge only the commits of 'from' that 'into' does not already have.
    public void merge(Branch from, Branch into) {
        int merged = 0;
        for (Commit c : from.getCommits()) {
            if (!into.contains(c.getId())) { into.add(c); merged++; }
        }
        final int m = merged;
        log.info(() -> "merge '" + from.getName() + "' -> '" + into.getName() + "': " + m + " commit(s)");
    }
}
