package com.bank.vcs;

import java.util.logging.*;

// Runnable demo: hotfix production WITHOUT shipping unreleased development work,
// then back-merge the hotfix into development.
public class BranchingDemo {
    private static final Logger log = Logger.getLogger(BranchingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — production vs development branching");

        Repo repo = new Repo();

        // production: exactly what is live (transfer service v1.0).
        Branch production = repo.createBranch("production", null);
        repo.commit(production, "transfer-service v1.0 (LIVE)");

        // development: branched from production, holds UNRELEASED work.
        Branch development = repo.createBranch("development", production);

        // A feature is built on a short-lived feature branch, merged to development.
        Branch feature = repo.createBranch("feature/upi-transfers", development);
        repo.commit(feature, "add UPI transfer support (NOT approved for prod)");
        repo.merge(feature, development);

        // CRITICAL BUG in LIVE: fee miscalculated for Rajesh/Priya transfers.
        log.warning("CRITICAL: production miscalculates transfer fees for SAV2001/CUR3001");

        // Hotfix branch cut from PRODUCTION (the exact live state) — NOT from development.
        Branch hotfix = repo.createBranch("hotfix/fee-calc", production);
        Commit fix = repo.commit(hotfix, "fix fee calculation (BigDecimal rounding)");

        // Deploy the hotfix to production: merge hotfix -> production. Unreleased UPI stays out.
        repo.merge(hotfix, production);
        log.info("production now has the fee fix; UPI feature is STILL unreleased (as intended)");

        // Back-merge the hotfix into development so it is not lost at the next release.
        repo.merge(hotfix, development);

        // Prove the separation.
        boolean prodHasUpi = production.contains(
            development.getCommits().stream()
                .filter(c -> c.getMessage().contains("UPI")).findFirst().map(Commit::getId).orElse("none"));
        boolean prodHasFix = production.contains(fix.getId());
        boolean devHasFix = development.contains(fix.getId());

        log.info("production has UPI (unreleased)? " + prodHasUpi + "  (expected false)");
        log.info("production has fee fix?          " + prodHasFix + "  (expected true)");
        log.info("development has fee fix?         " + devHasFix + "  (expected true — back-merged)");
    }
}
